 * @param {string|undefined} observedModel
 * @param {{model?:string, extra?:Record<string,unknown>}} input
 * @returns {string|undefined}
 */
export function normalizeObservedModel(observedModel, input) {
  if (!observedModel) {
    return observedModel;
